7	/**
8	 * Assigns the {@code namesakeCount} to a newly built owner: the number of existing owners that
9	 * share the same firstName and lastName, compared case-insensitively. Runs before the owner is
10	 * saved, so the count reflects the owners that existed before this create and excludes the owner
11	 * being created.
12	 */
13	public class AssignNamesakeCount {
14	
15	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
16	        String firstName = owner.getFirstName();
17	        String lastName = owner.getLastName();
18	        int count = 0;
19	        for (Owner existing : ownerRepository.findAll()) {
20	            if (firstName.equalsIgnoreCase(existing.getFirstName())
